import{_ as t,q as a,f as r,ad as i}from"./chunks/framework.BuQdu_o1.js";const f=JSON.parse(`{"title":"Max Konyi's feeling states","description":"","frontmatter":{},"headers":[],"relativePath":"theory/intervals/Max Konyi's feeling states.md","filePath":"theory/intervals/Max Konyi's feeling states.md","lastUpdated":1787982428000}`),n={name:"theory/intervals/Max Konyi's feeling states.md"};function h(l,e,o,s,d,c){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="max-konyi-s-feeling-states" tabindex="-1">Max Konyi&#39;s feeling states <a class="header-anchor" href="#max-konyi-s-feeling-states" aria-label="Permalink to “Max Konyi&#39;s feeling states”">​</a></h1><p>A granular look into Max Konyi&#39;s framework reveals that each of the 12 chromatic scale degrees acts as a distinct emotional ecosystem when measured against a steady tonic drone.</p><h2 id="the-12-feeling-states-in-depth" tabindex="-1">The 12 Feeling-States in Depth <a class="header-anchor" href="#the-12-feeling-states-in-depth" aria-label="Permalink to “The 12 Feeling-States in Depth”">​</a></h2><h3 id="_1-degree-1-the-tonic" tabindex="-1">1. Degree 1 (The Tonic) <a class="header-anchor" href="#_1-degree-1-the-tonic" aria-label="Permalink to “1. Degree 1 (The Tonic)”">​</a></h3><ul><li><strong>Deep Character:</strong> Home base and the fundamental reference point around which the ear organizes all musical space. It represents the &quot;minimum energy&quot; state within a key—an absolute bedrock of rest and resolution where motion ceases and nothing feels left hanging or unfinished. It is the zero point of tension.</li></ul><h3 id="_2-degree-5-the-fifth" tabindex="-1">2. Degree 5 (The Fifth) <a class="header-anchor" href="#_2-degree-5-the-fifth" aria-label="Permalink to “2. Degree 5 (The Fifth)”">​</a></h3><ul><li><strong>Deep Character:</strong> The closest relative to the tonic without being the tonic itself. It is open, highly consonant, and deeply expansive, but unlike the complete stillness of home base, it pulses with a quiet, steady vitality. It anchors an entire dimension of clean, clear, and emotionally neutral sound.</li></ul><h3 id="_3-degree-3-the-third" tabindex="-1">3. Degree 3 (The Third) <a class="header-anchor" href="#_3-degree-3-the-third" aria-label="Permalink to “3. Degree 3 (The Third)”">​</a></h3><ul><li><strong>Deep Character:</strong> The primary pillar of major tonality. It introduces a vital axis of warmth, organic presence, and life. Rather than pure architectural neutrality, the major third radiates a soft, glowing illumination that colors the entire harmonic space around it.</li></ul><h3 id="_4-degree-2-the-second" tabindex="-1">4. Degree 2 (The Second) <a class="header-anchor" href="#_4-degree-2-the-second" aria-label="Permalink to “4. Degree 2 (The Second)”">​</a></h3><ul><li><strong>Deep Character:</strong> Clean, pure, and structurally sharp, yet emotionally calm and balanced. It sits cleanly in the neutral family alongside degrees 1, 4, and 5, offering a clear and defined step that feels crisp without carrying heavy emotional baggage.</li></ul><h3 id="_5-degree-4-the-fourth" tabindex="-1">5. Degree 4 (The Fourth) <a class="header-anchor" href="#_5-degree-4-the-fourth" aria-label="Permalink to “5. Degree 4 (The Fourth)”">​</a></h3><ul><li><strong>Deep Character:</strong> While it shares the clean, consonant neutrality of the fifth (being its direct inverse a fifth below the tonic), it behaves with an intentional contraction. Where the fifth feels like it opens outward into the sky, the fourth curls inward, creating a focused, inward-pulling gravity.</li></ul><h3 id="_6-degree-6-the-sixth" tabindex="-1">6. Degree 6 (The Sixth) <a class="header-anchor" href="#_6-degree-6-the-sixth" aria-label="Permalink to “6. Degree 6 (The Sixth)”">​</a></h3><ul><li><strong>Deep Character:</strong> A lighter, more softened reflection of the major third. It retains warmth and pleasantness, but in a muted, pastel, or cooler tone—acting almost like a bridge where the structural neutrality of the fourth meets the organic life of the third.</li></ul><h3 id="_7-degree-7-the-seventh" tabindex="-1">7. Degree 7 (The Seventh) <a class="header-anchor" href="#_7-degree-7-the-seventh" aria-label="Permalink to “7. Degree 7 (The Seventh)”">​</a></h3><ul><li><strong>Deep Character:</strong> Positioned just a semitone beneath the tonic, it generates a potent blend of the fifth and third. Far from just a &quot;leading tone&quot; demanding an immediate physical resolution to home, it possesses a standalone, bittersweet, and vibrant tension full of life and delicate longing.</li></ul><h3 id="_8-degree-♯4-♭5-the-sharp-fourth-tritone" tabindex="-1">8. Degree ♯4 / ♭5 (The Sharp Fourth / Tritone) <a class="header-anchor" href="#_8-degree-♯4-♭5-the-sharp-fourth-tritone" aria-label="Permalink to “8. Degree ♯4 / ♭5 (The Sharp Fourth / Tritone)”">​</a></h3><ul><li><strong>Deep Character:</strong> A striking, high-voltage anomaly sitting right in the middle of the scale. It radiates intense, bright tension with a strange, otherworldly edge, acting as an alien, electric focal point that splits the octave right down the middle.</li></ul><h3 id="_9-degree-♭7-the-flat-seventh" tabindex="-1">9. Degree ♭7 (The Flat Seventh) <a class="header-anchor" href="#_9-degree-♭7-the-flat-seventh" aria-label="Permalink to “9. Degree ♭7 (The Flat Seventh)”">​</a></h3><ul><li><strong>Deep Character:</strong> The lightest and most open of the flat/minor-leaning degrees. It carries a relaxed, floating tension that feels naturally bluesy, earthy, and soulful, lacking the sharp bite of heavier intervals.</li></ul><h3 id="_10-degree-♭3-the-flat-third" tabindex="-1">10. Degree ♭3 (The Flat Third) <a class="header-anchor" href="#_10-degree-♭3-the-flat-third" aria-label="Permalink to “10. Degree ♭3 (The Flat Third)”">​</a></h3><ul><li><strong>Deep Character:</strong> The emotional cornerstone of minor keys. It shifts the musical landscape into a serious, solemn, and deeply introspective space, carrying a darker, more melancholic gravity than the flat seventh.</li></ul><h3 id="_11-degree-♭6-the-flat-sixth" tabindex="-1">11. Degree ♭6 (The Flat Sixth) <a class="header-anchor" href="#_11-degree-♭6-the-flat-sixth" aria-label="Permalink to “11. Degree ♭6 (The Flat Sixth)”">​</a></h3><ul><li><strong>Deep Character:</strong> Deeper, darker, and emotionally heavier than the flat third. It introduces a profound gravity and solemn weight, pulling the listener into a somber, shadowed emotional space.</li></ul><h3 id="_12-degree-♭2-the-flat-second" tabindex="-1">12. Degree ♭2 (The Flat Second) <a class="header-anchor" href="#_12-degree-♭2-the-flat-second" aria-label="Permalink to “12. Degree ♭2 (The Flat Second)”">​</a></h3><ul><li><strong>Deep Character:</strong> Melodically sitting just a single semitone above the tonic, it is intimately close by pitch yet maximally distant in emotional harmony. It creates an intensely dark, sharp, and in-your-face friction that feels provocative and arresting.</li></ul><hr><p>To hear these nuances demonstrated live over a continuous drone, watch <a href="https://www.youtube.com/watch?v=AARDtj6wL3U" target="_blank" rel="noreferrer">A Guided Tour of Musical Feeling</a>.</p>',29)])])}const u=t(n,[["render",h]]);export{f as __pageData,u as default};
